133:     {
134:         private SourceProductionContext context;
135: 
136:         public GeneratorContext(SourceProductionContext context)
137:         {
138:             this.context = context;
139:         }
140: 
141:         public CancellationToken CancellationToken => context.CancellationToken;
142: 
143:         public void AddSource(string hintName, string source) => context.AddSource(hintName, source);
144: 
145:         public void ReportDiagnostic(Diagnostic diagnostic) => context.ReportDiagnostic(diagnostic);
146:     }
147: }

