24:         var unionTypes = context.SyntaxProvider.ForAttributeWithMetadataName(
25:             $"{AttributeNamespace}.{MessagePackUnionAttributeName}",
26:             predicate: static (node, _) => node is InterfaceDeclarationSyntax,
27:             transform: static (context, _) => (ITypeSymbol)context.TargetSymbol);
28: 
29:         var combined =
30:             messagePackObjectTypes.Collect().Combine(unionTypes.Collect());
31: 
32:         var source = combined
33:             .Combine(context.CompilationProvider)
34:             .Combine(options)
35:             .Select(static (s, ct) =>
36:             {
37:                 AnalyzerOptions options = s.Right;
38: 
39:                 if (!ReferenceSymbols.TryCreate(s.Left.Right, out ReferenceSymbols? referenceSymbols) || referenceSymbols.MessagePackFormatter is null)
40:                 {
41:                     return default;
42:                 }
43: 
44:                 List<FullModel> modelPerType = new();
45:                 void Collect(ITypeSymbol typeSymbol)
46:                 {
47:                     if (TypeCollector.Collect(s.Left.Right, options, referenceSymbols, reportAnalyzerDiagnostic: null, typeSymbol, ct) is FullModel model)
48:                     {
49:                         modelPerType.Add(model);
50:                     }
51:                 }
52: 
53:                 foreach (var typeSymbol in s.Left.Left.Left)
54:                 {
55:                     Collect(typeSymbol);
56:                 }
57: 
58:                 foreach (var typeSymbol in s.Left.Left.Right)
59:                 {
60:                     Collect(typeSymbol);
61:                 }
62: 
63:                 if (!options.KnownFormatters.IsEmpty)
64:                 {
65:                     var customFormatterInfos = FullModel.Empty.CustomFormatterInfos.Union(
66:                         from known in options.KnownFormatters
67:                         where known.InaccessibleDescriptor is null
68:                         from formatted in known.FormattableTypes
69:                         where !options.GetCollidingFormatterDataTypes(known.Name).Contains(formatted) // skip formatters with colliding types to avoid non-deterministic code generation
70:                         select new CustomFormatterRegisterInfo
71:                         {
72:                             Formatter = known.Name,
73:                             DataType = formatted.Name,
74:                             FormattableDataType = formatted,
75:                             CustomFormatter = known,
76:                         });
77:                     modelPerType.Add(FullModel.Empty with { CustomFormatterInfos = customFormatterInfos, Options = options });
78:                 }
79: 
80:                 return FullModel.Combine(modelPerType.ToImmutableArray());
81:             });
82: 
83:         var splittedSources = source
84:             .SelectMany(static (s, ct) =>
85:             {
86:                 if (s is null)
