109:         public Test AddGeneratedSources()
110:         {
111:             static void AddGeneratedSources(ProjectState project, string testMethod, bool withPrefix)
112:             {
113:                 string prefix = withPrefix ? $"{project.Name}." : string.Empty;
114:                 string expectedPrefix = $"{ThisAssembly.AssemblyName}.Resources.{testMethod}.{prefix}"
115:                     .Replace(' ', '_')
116:                     .Replace(',', '_')
117:                     .Replace('(', '_')
118:                     .Replace(')', '_');
119: 
120:                 foreach (var resourceName in typeof(Test).Assembly.GetManifestResourceNames())
121:                 {
122:                     if (!resourceName.StartsWith(expectedPrefix))
123:                     {
124:                         continue;
125:                     }
126: 
127:                     using var resourceStream = Assembly.GetExecutingAssembly().GetManifestResourceStream(resourceName);
128:                     if (resourceStream is null)
129:                     {
130:                         throw new InvalidOperationException();
131:                     }
132: 
133:                     using var reader = new StreamReader(resourceStream, Encoding.UTF8, detectEncodingFromByteOrderMarks: true, bufferSize: 4096, leaveOpen: true);
134:                     var name = resourceName.Substring(expectedPrefix.Length);
135:                     project.GeneratedSources.Add((typeof(TSourceGenerator), name, reader.ReadToEnd()));
136:                 }
137:             }
138: 
139:             AddGeneratedSources(this.TestState, this.testMethod, this.TestState.AdditionalProjects.Count > 0);
140:             foreach (ProjectState addlProject in this.TestState.AdditionalProjects.Values)
141:             {
142:                 AddGeneratedSources(addlProject, this.testMethod, true);
143:             }
144: 
145:             return this;
146:         }
147: 
148:         protected override Task RunImplAsync(CancellationToken cancellationToken)
149:         {
150:             this.AddGeneratedSources();
151: 
152:             foreach (ProjectState addlProject in this.TestState.AdditionalProjects.Values)
153:             {
154:                 addlProject.AdditionalReferences.AddRange(this.TestState.AdditionalReferences);
155:                 addlProject.DocumentationMode = DocumentationMode.Parse;
156:             }
157: 
158:             return base.RunImplAsync(cancellationToken);
159:         }
