188:         protected override async Task<(Compilation, ImmutableArray<Diagnostic>)> GetProjectCompilationAsync(Project project, IVerifier verifier, CancellationToken cancellationToken)
189:         {
190:             string fileNamePrefix = this.TestState.AdditionalProjects.Count > 0 ? $"{project.Name}." : string.Empty;
191:             var resourceDirectory = Path.Combine(Path.GetDirectoryName(this.testFile)!, "Resources", this.testMethod);
192: 
193:             var (compilation, diagnostics) = await base.GetProjectCompilationAsync(project, verifier, cancellationToken);
194:             var expectedNames = new HashSet<string>();
195:             foreach (var tree in compilation.SyntaxTrees.Skip(project.DocumentIds.Count))
196:             {
197:                 WriteTreeToDiskIfNecessary(tree, resourceDirectory, fileNamePrefix);
198:                 expectedNames.Add(Path.GetFileName(tree.FilePath));
199:             }
200: 
201:             var currentTestPrefix = $"{ThisAssembly.AssemblyName}.Resources.{this.testMethod}.{fileNamePrefix}";
202:             foreach (var name in this.GetType().Assembly.GetManifestResourceNames())
203:             {
204:                 if (!name.StartsWith(currentTestPrefix))
205:                 {
206:                     continue;
207:                 }
208: 
209:                 if (!expectedNames.Contains(name.Substring(currentTestPrefix.Length)))
210:                 {
211:                     throw new InvalidOperationException($"Unexpected test resource: {name.Substring(currentTestPrefix.Length)}");
212:                 }
213:             }
214: 
215:             return (compilation, diagnostics);
216:         }
217: 
218:         [Conditional("WRITE_EXPECTED")]
219:         private static void WriteTreeToDiskIfNecessary(SyntaxTree tree, string resourceDirectory, string fileNamePrefix)
220:         {
221:             if (tree.Encoding is null)
222:             {
223:                 throw new ArgumentException("Syntax tree encoding was not specified");
224:             }
225: 
226:             string name = fileNamePrefix + Path.GetFileName(tree.FilePath);
227:             string filePath = Path.Combine(resourceDirectory, name);
228:             Directory.CreateDirectory(resourceDirectory);
229:             File.WriteAllText(filePath, tree.GetText().ToString(), tree.Encoding);
230:         }
231:     }
